VISUAL_REVIEW_OVERRIDES.update(BATCH22_STRUCTURAL_OVERRIDES)


# Batch 22 follow-up: remove a few false conjunctions introduced by the prior
# mechanical initial-letter pass; the PDF shows these words begin the verse
